    names=load(doc['speaker_name_review']);require(all(names[k] for k in ['both_actual_final_English_personal_names_complete','two_contextual_progressive_names_retained_no_assets_or_duplicate_credit','both_null_middle_fields_andsame_text_full_getters_preserved','no_surname_nationality_occupation_kinship_or_rank_inferred','full_catalogue_UI_unvisited','full207_name_role_alias_andearlier_name_review_open','source_item97_no_asset_card_mechanic_orother_consumer_approval','progressive_header_display_only_not_full_catalogue_UI_approval','no_new_name_or_dialogue_credit']),'name consumers andscope')
