    r=item['source_named_item'];require((r['record_ID'],r['Japanese'],r['English'],r['source_terminated_hex'],r['current_terminated_hex'])==('DK4_ITEM_POINTER_097','フェイディアスの鑿',"Phidias' Chisel",'837483468343836683428341835882cce87700','50686964696173272043686973656c00'),'exact source-bound item97');fields(r)
    require((r['pointer_field'],r['source_storage_offset'],r['current_storage_kind'],r['current_storage_offset'])==(1174312,1436432,'static-current-ARM9',1435672) and r['current_native_item_getter_card_bounds_mechanics_and_all_other_consumers_not_reviewed_here'],'item97 exact static storage;other consumers not newly approved')
    np=load(doc['native_name_proof']);require(np['name_literal_alignment_count']==np['exact_reused_native_name_font_alignment_cases']==24 and np['fresh_native_name_font_alignment_cases']==0 and np['complete_name_component_plane_count']==len(np['name_planes'])==6 and sum(len(r['native_alignment']['cases']) for r in np['name_planes'])==24 and {r['text'] for r in np['name_planes']}=={'Lil Argot','Manuel Almeida','Lil','Argot','Manuel','Almeida'} and np['source_personal_fields_Lil_Argot_Manuel_Almeida_match_both_original_getters'] and np['no_surname_nationality_occupation_or_scene_location_inferred_from_secondary_field'] and np['all_first_internal_final_name_glyphs_and_zero_ink_flushes_complete'] and np['no_name_asset_or_duplicate_credit'] and np['all_current_B233_name_getters_freshly_bound_in_separate_consumer_proof'],'six exact reused name planes24 alignments;zero fresh name executions')
    entry=load(doc['source_entry_proof']);require(sha(Path(doc['source_entry_proof']).read_bytes())==doc['source_entry_proof_sha256'] and entry['original_source_EV2_and_action_table_exact'] and [(r['event_ID'],r['script_block'],r['action_index'],r['must_be_completed'],r['must_not_be_completed']) for r in entry['selected_B233_source_events']]==[(233,233,234,[232],[])],'original233 requires232;not forced eligibility')

    a,l=load(doc['actual_English_proof']),load(doc['later_scope_proof']);o=mapping['observed_comparison_contract']
    measured=dict(source_exit=a['source_exit_frame'],English_exit=a['exit_frame'],normal_port=a['normal_port_sample_frame'],body_holds=a['actual_complete_body_holds'],name_holds=a['actual_complete_name_holds'],command_difference_rows=len(a['command_comparison_differences']),duration_changes=len(a['command_duration_changes']),later_samples=len(a['later_sampled_whole_frame_comparisons']),later_RGB_differences=len(l['later_sampled_RGB_differences']),component_equality=l['five_native_component_equality'],captains=l['captain_IDs'],PRNG_seeds=l['final_PRNG_seeds'],following_B120_ends=[r['B120_end_frames'] for r in l['following_B120']])
